    for i in range(gi.shape[0]):
        for j in range(gi.shape[1]):
            if gi[i,j]!=0 and not seen[i,j]:
                st=[(i,j)]; cl=set()
                while st:
                    a,b=st.pop()
                    if 0<=a<gi.shape[0] and 0<=b<gi.shape[1] and gi[a,b]==gi[i,j] and not seen[a,b]:
                        seen[a,b]=True; cl.add((a,b)); st+=[(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                out.append((int(gi[i,j]),sorted(cl)))
    return out
def zregions(gi):
    H,W=gi.shape
    seen=np.zeros((H,W),bool); res=[]
    for i in range(H):
        for j in range(W):
            if gi[i,j]==0 and not seen[i,j]:
                st=[(i,j)]; comp=set(); touch=False
                while st:
                    a,b=st.pop()
                    if a==0 or b==0 or a==H-1 or b==W-1: touch=True
                    if 0<=a<H and 0<=b<W and gi[a][b]==0 and not seen[a,b]:
                        seen[a,b]=True; comp.add((a,b)); st+=[(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                if not touch: res.append(comp)
    return res
def solve(g):
    g=[list(map(int,r)) for r in g]; H,W=len(g),len(g[0])
    gi=np.array(g)
    cs=comps_color(gi)
    seeds=[(c,cset) for c,cset in cs if len(cset)>1]
    out=[row[:] for row in g]
    for reg in zregions(gi):
        best=min(seeds,key=lambda s:min(abs(r-a)+abs(c-b) for r,c in s[1] for a,b in reg))
        col,scl=best
        rs=[p[0] for p in scl]; ss=[p[1] for p in scl]
        sr,sc2=min(rs),min(ss)
        ph,pw=max(rs)-sr+1,max(ss)-sc2+1
        pat={ (r-sr,c-sc2):col for r,c in scl }
        # anchor: region bbox top-left maps to pattern origin
        r0,c0=min(p[0] for p in reg),min(p[1] for p in reg)
        for a,b in reg:
            out[a][b]=pat.get(((a-r0)%ph,(b-c0)%pw),0)
    return out
